CREATE TABLE IF NOT EXISTS "users" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "username" TEXT NOT NULL UNIQUE, "full_name" TEXT NOT NULL, "password_hash" TEXT NOT NULL, "role" TEXT NOT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "last_login_at" INTEGER NULL);
CREATE TABLE IF NOT EXISTS "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "units" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "products" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "code" TEXT NOT NULL UNIQUE, "barcode" TEXT NULL UNIQUE, "name" TEXT NOT NULL, "category_id" INTEGER NULL REFERENCES categories (id), "unit_id" INTEGER NULL REFERENCES units (id), "purchase_price" INTEGER NOT NULL DEFAULT 0, "selling_price" INTEGER NOT NULL DEFAULT 0, "stock" REAL NOT NULL DEFAULT 0.0, "min_stock" REAL NOT NULL DEFAULT 0.0, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE IF NOT EXISTS "sales" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "invoice_no" TEXT NOT NULL UNIQUE, "sale_date" INTEGER NOT NULL, "user_id" INTEGER NOT NULL REFERENCES users (id), "item_count" INTEGER NOT NULL, "subtotal" INTEGER NOT NULL, "discount_percent" REAL NULL, "discount" INTEGER NOT NULL DEFAULT 0, "total" INTEGER NOT NULL, "paid" INTEGER NOT NULL, "change_amount" INTEGER NOT NULL, "payment_method" TEXT NOT NULL DEFAULT 'tunai', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE IF NOT EXISTS "sale_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sale_id" INTEGER NOT NULL REFERENCES sales (id) ON DELETE CASCADE, "product_id" INTEGER NOT NULL REFERENCES products (id), "product_code" TEXT NOT NULL, "product_name" TEXT NOT NULL, "unit_name" TEXT NULL, "qty" REAL NOT NULL, "price" INTEGER NOT NULL, "discount_percent" REAL NOT NULL DEFAULT 0.0, "purchase_price" INTEGER NOT NULL, "subtotal" INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS "stock_movements" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "product_id" INTEGER NOT NULL REFERENCES products (id), "type" TEXT NOT NULL, "qty_change" REAL NOT NULL, "ref_id" INTEGER NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE INDEX idx_products_name ON products (name);
CREATE INDEX idx_sales_date ON sales (sale_date);
